function expandRepeats(s) {
  const stack = []
  let current = ''
  let count = 0
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') {
      count = count * 10 + Number(ch)
    } else if (ch === '[') {
      stack.push([current, count])
      current = ''
      count = 0
    } else if (ch === ']') {
      const [prev, k] = stack.pop()
      current = prev + current.repeat(k)
    } else {
      current += ch
    }
  }
  return current
}

