def expand_repeats(s):
    stack = []
    parts = []
    count = 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == "[":
            stack.append((parts, count))
            parts, count = [], 0
        elif ch == "]":
            prev, k = stack.pop()
            prev.append("".join(parts) * k)
            parts = prev
        else:
            parts.append(ch)
    return "".join(parts)
